"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('omar', 17), ('omar', 24), ('mia', 33), ('noor', 16), ('noor', 14), ('noor', 9)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)


def feed_donations():
    """Endless feed of donations: repeats the stored rows for ever."""
    while True:
        for donor, pounds in ROWS:
            yield Donation(donor, pounds)

