"""Halves of a window over the donations feed."""
import itertools


def split_window(feed, size):
    """Read the next `size` donations from the feed and return their pounds as (first half, second half).

    The feed may be endless. Exactly `size` items are read from it.
    """
    window = [x.pounds for x in itertools.islice(feed, size)]
    half = size // 2
    return window[:half], window[size:]


def describe_donation(donation):
    """Return a one-line description of a donation."""
    return "%s: %s" % (donation.donor, donation.pounds)


def group_by_donor(donations):
    """Return a dict from donor to the list of donations with that donor."""
    groups = {}
    for x in donations:
        groups.setdefault(x.donor, []).append(x)
    return groups
